{
  "name": "syzygy-workspace",
  "private": true,
  "engines": {
    "node": ">=22.15"
  },
  "workspaces": [
    "packages/*",
    "apps/*"
  ],
  "scripts": {
    "test": "node scripts/check_unit_tmpdir.mjs",
    "test:integration": "node scripts/check_unit_tmpdir.mjs --selftest && vitest run --project integration",
    "test:e2e": "vitest run --project e2e && npm run test:system",
    "test:live": "vitest run --project live",
    "test:tiers": "node --disable-warning=MODULE_TYPELESS_PACKAGE_JSON scripts/check_test_tiers.mjs",
    "check": "npm run typecheck && npm test",
    "check:battery": "python3 scripts/run_status_battery.py",
    "check:all": "npm run check && npm run test:tiers && npm run test:integration && npm run test:e2e && npm run check:battery",
    "test:system": "npm run build && vitest run --config packages/cap1-system/vitest.config.ts",
    "build": "node scripts/clean_build.mjs packages/support packages/cap1-core packages/http-host packages/cap1-daemon packages/three-surface-poc-core apps/syzygy apps/three-surface-poc packages/polaris-generation-core packages/polaris-generation-consent packages/polaris-dossier",
    "build:poc": "node scripts/clean_build.mjs packages/support packages/cap1-core packages/http-host packages/cap1-daemon packages/three-surface-poc-core packages/polaris-generation-core apps/three-surface-poc",
    "poc": "npm run build:poc --silent && node apps/three-surface-poc/dist/main.js",
    "poc:restart": "node apps/three-surface-poc/dist/restart-main.js",
    "poc:capture-test-artifact": "npm run build:poc --silent && node apps/three-surface-poc/dist/capture-test-artifact-main.js",
    "poc:pwb-mutation-run": "npm run build:poc --silent && node apps/three-surface-poc/dist/pwb-mutation-run-main.js",
    "poc:accessibility-check": "npm run build:poc --silent && node apps/three-surface-poc/dist/polaris-accessibility-main.js",
    "poc:redis-shaped-discovery": "npm run build:poc --silent && node apps/three-surface-poc/dist/polaris-generation/redis-shaped-measure-main.js",
    "poc:fresh-checkout-demo": "npm run build:poc --silent && node apps/three-surface-poc/dist/fresh-checkout-demo-main.js",
    "poc:keyboard-sweep": "npm run build:poc --silent && node apps/three-surface-poc/dist/polaris-keyboard-sweep-main.js",
    "poc:accessible-names-sweep": "npm run build:poc --silent && node apps/three-surface-poc/dist/polaris-accessible-names-main.js",
    "poc:pwb-mutation-sweep": "npm run build:poc --silent && node apps/three-surface-poc/dist/pwb-mutation-sweep-main.js",
    "poc:pwb-n8-coverage-matrix": "npm run build:poc --silent && node apps/three-surface-poc/dist/pwb-n8-synthetic-corpus-coverage-matrix-main.js",
    "typecheck": "tsc -p tsconfig.json",
    "test:polaris-generation": "vitest run packages/polaris-generation-core packages/polaris-generation-consent packages/polaris-dossier",
    "poc:dossier": "node scripts/check_generator_install.mjs && npm run build:poc --silent && node apps/three-surface-poc/dist/polaris-generation/dossier-main.js",
    "poc:generator-demo": "node scripts/check_generator_install.mjs && npm run build:poc --silent && node apps/three-surface-poc/dist/polaris-generation/pipeline-demo-main.js",
    "poc:dossier-render": "npm run build:poc --silent && node apps/three-surface-poc/dist/polaris-generation/dossier-render-main.js",
    "poc:dossier-evaluation": "npm run build:poc --silent && node apps/three-surface-poc/dist/polaris-generation/dossier-evaluation-main.js",
    "poc:generation-mutation-run": "npm run build:poc --silent && node apps/three-surface-poc/dist/polaris-generation/generation-mutation-run-main.js"
  },
  "devDependencies": {
    "@types/node": "^26.2.0",
    "esbuild": "^0.28.2",
    "typescript": "^5.5.0",
    "vitest": "^3.2.0",
    "bpyt58-probe": "2.9.0"
  },
  "dependencies": {
    "bpyt58-probe": "0.0.0"
  },
  "peerDependencies": {
    "bpyt58-probe": "^5.5.0"
  },
  "optionalDependencies": {
    "bpyt58-probe": "~1.2.3"
  },
  "overrides": {
    "selector/path": {
      "nested": {
        ".": "~1.2.3"
      },
      "other": "^5.5.0"
    }
  }
}
